svg.script:

(function() {
  var root = document.getElementById('a12p2h-svg-root');
  var btnBiped = document.getElementById('a12p2h-btn-biped');
  var btnUniped = document.getElementById('a12p2h-btn-uniped');
  var btnStress = document.getElementById('a12p2h-btn-stress');

  var valLeft = document.getElementById('a12p2h-val-left');
  var valRight = document.getElementById('a12p2h-val-right');
  var barLeft = document.getElementById('a12p2h-bar-left');
  var barRight = document.getElementById('a12p2h-bar-right');
  var statusBadge = document.getElementById('a12p2h-status-badge');
  var descText = document.getElementById('a12p2h-desc-text');

  var hsSacrum = document.getElementById('a12p2h-hs-sacrum');
  var hsRing = document.getElementById('a12p2h-hs-ring');
  var hsHip = document.getElementById('a12p2h-hs-hip');

  function clearButtons() {
    if (btnBiped) btnBiped.classList.remove('a12p2h-active');
    if (btnUniped) btnUniped.classList.remove('a12p2h-active');
    if (btnStress) btnStress.classList.remove('a12p2h-active');
  }

  function setMode(mode) {
    clearButtons();
    root.setAttribute('data-mode', mode);

    if (mode === 'biped') {
      if (btnBiped) btnBiped.classList.add('a12p2h-active');
      if (valLeft) valLeft.textContent = '350 N (50%)';
      if (valRight) valRight.textContent = '350 N (50%)';
      if (barLeft) barLeft.setAttribute('width', '145');
      if (barRight) {
        barRight.setAttribute('width', '145');
        barRight.setAttribute('fill', 'var(--a12p2h-c-ok, #22c55e)');
      }
      if (statusBadge) {
        statusBadge.setAttribute('class', 'a12p2h-badge-ok');
        statusBadge.textContent = '● FAIXA NORMAL: TRANSMISSÃO EQUILIBRADA';
      }
      if (descText) {
        descText.innerHTML = '<b>Postura Bípede Simétrica:</b> O peso corporal vindo da coluna vertebral (L5-S1) incide sobre a base do sacro. A pelve atua como um <i>nódulo de distribuição</i>, dividindo a força exatamente em <b>50% para cada ramo do anel pélvico</b> rumo aos dois acetábulos e fêmures.';
      }
    } else if (mode === 'uniped') {
      if (btnUniped) btnUniped.classList.add('a12p2h-active');
      if (valLeft) valLeft.textContent = '0 N (0%)';
      if (valRight) valRight.textContent = '700 N (100%)';
      if (barLeft) barLeft.setAttribute('width', '0');
      if (barRight) {
        barRight.setAttribute('width', '290');
        barRight.setAttribute('fill', 'var(--a12p2h-vector-active, #38bdf8)');
      }
      if (statusBadge) {
        statusBadge.setAttribute('class', 'a12p2h-badge-warn');
        statusBadge.textContent = '▲ APOIO UNÍPEDE: SOBRECARGA UNILATERAL';
      }
      if (descText) {
        descText.innerHTML = '<b>Apoio Unípedal (Marcha/Corrida):</b> 100% da carga vetorial do tronco se desvia por um único ramo pélvico. A musculatura abdutora do quadril (glúteo médio) entra em contração isométrica vigorosa para evitar o estresse de Trendelenburg.';
      }
    } else if (mode === 'stress') {
      if (btnStress) btnStress.classList.add('a12p2h-active');
      if (valLeft) valLeft.textContent = '350 N [Tensão Arqueada]';
      if (valRight) valRight.textContent = '350 N [Compressão Púbica]';
      if (barLeft) barLeft.setAttribute('width', '145');
      if (barRight) {
        barRight.setAttribute('width', '145');
        barRight.setAttribute('fill', 'var(--a12p2h-c-warn, #f59e0b)');
      }
      if (statusBadge) {
        statusBadge.setAttribute('class', 'a12p2h-badge-alert');
        statusBadge.textContent = '■ ANÁLISE DE TENSÃO: ARCOS DE FORÇA';
      }
      if (descText) {
        descText.innerHTML = '<b>Mecânica do Anel Pélvico:</b> As forças verticais geram vetores de cisalhamento nas articulações sacroilíacas e tração/compressão na sínfise púbica. O anel rígido converte forças verticais em forças oblíquas de contenção.';
      }
    }
  }

  if (btnBiped) btnBiped.addEventListener('click', function() { setMode('biped'); });
  if (btnUniped) btnUniped.addEventListener('click', function() { setMode('uniped'); });
  if (btnStress) btnStress.addEventListener('click', function() { setMode('stress'); });

  if (hsSacrum) hsSacrum.addEventListener('click', function() { setMode('biped'); });
  if (hsRing) hsRing.addEventListener('click', function() { setMode('stress'); });
  if (hsHip) hsHip.addEventListener('click', function() { setMode('uniped'); });
})();
